const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const flintHills = ee.Geometry.Rectangle([-97.5, 37.0, -96.0, 39.0]);

  const date1 = '2023-03-19';
  const date2 = '2023-04-08';

  // 2. Data Acquisition
  function getSentinel2Image(date) {
    const startDate = ee.Date(date);
    const endDate = startDate.advance(1, 'day');

    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(flintHills)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    // Check if collection is empty
    const size = collection.size().getInfo();
    if (size === 0) {
      console.log(`No Sentinel-2 images found for ${date}`);
      return null;
    }

    // Get least cloudy image and apply cloud mask
    const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();

    // Cloud masking using QA60 band
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    return image.updateMask(mask).clip(flintHills);
  }

  const img1 = getSentinel2Image(date1);
  const img2 = getSentinel2Image(date2);

  // Check for empty collections
  if (!img1 || !img2) {
    console.log(`${date1} Images: ${img1 ? 'Found' : '0'}`);
    console.log(`${date2} Images: ${img2 ? 'Found' : '0'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate NBR for burn scar detection
  function calculateNBR(img) {
    const nir = img.select('B8');
    const swir = img.select('B12');
    return nir.subtract(swir).divide(nir.add(swir)).rename('NBR');
  }

  const nbr1 = calculateNBR(img1);
  const nbr2 = calculateNBR(img2);

  // 4. Count burn scar pixels (NBR < 0.2 indicates burn scars)
  function countBurnScars(nbrImg) {
    const burnMask = nbrImg.lt(0.2);

    const count = burnMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: flintHills,
      scale: 1000,
      maxPixels: 1e9
    }).get('NBR').getInfo();

    const totalPixels = burnMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: flintHills,
      scale: 1000,
      maxPixels: 1e9
    }).get('NBR').getInfo();

    return {burnCount: count, totalPixels: totalPixels};
  }

  const stats1 = countBurnScars(nbr1);
  const stats2 = countBurnScars(nbr2);

  // 5. Validation & Final Answer
  console.log(`${date1}: Burn scar pixels: ${stats1.burnCount}, Total: ${stats1.totalPixels}`);
  console.log(`${date2}: Burn scar pixels: ${stats2.burnCount}, Total: ${stats2.totalPixels}`);

  // Check for no valid pixels
  if (stats1.totalPixels === 0 || stats2.totalPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (stats1.burnCount === null || stats2.burnCount === null || 
      isNaN(stats1.burnCount) || isNaN(stats2.burnCount)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare burn scar extent
  const increase = stats2.burnCount > stats1.burnCount;
  console.log(`Burn scar change: ${increase ? 'Increased' : 'Decreased/No change'}`);

  if (increase) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
